class Solution {
  public int findWinningPlayer(int[] skills, int k) {
    // the queue rotates, so the current champion only ever meets each later player once
    int champion = 0, wins = 0;
    for (int i = 1; i < skills.length && wins < k; i++) {
      if (skills[champion] > skills[i]) {
        wins++;
      } else {
        champion = i;
        wins = 1;
      }
    }
    return champion;
  }
}
